-- Additional completion controls. Synthetic transaction only; no customer mail.
begin;
create temp table completion_threshold_ids(id uuid,expected text);
grant select,insert on completion_threshold_ids to authenticated;
create temp table completion_portal_ids(request_id uuid,share_id uuid,customer_id uuid);
grant select,insert on completion_portal_ids to authenticated,anon;
create temp table work_test_ids(owner_id uuid,editor_id uuid,session_id uuid,editor_session uuid,factor_id uuid,editor_factor uuid);
insert into work_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on work_test_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at) select owner_id,'owner-fixture@example.invalid',now() from work_test_ids union all select editor_id,'editor-fixture@example.invalid',now() from work_test_ids;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select factor_id,owner_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids union all select editor_factor,editor_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids;
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) select session_id,owner_id,factor_id,'aal2'::auth.aal_level,now(),now() from work_test_ids union all select editor_session,editor_id,editor_factor,'aal2'::auth.aal_level,now(),now() from work_test_ids;
insert into public.work_members(email,user_id,role) select 'owner-fixture@example.invalid',owner_id,'owner' from work_test_ids union all select 'editor-fixture@example.invalid',editor_id,'editor' from work_test_ids;
insert into private.work_job_config(id,proof_hash) values(1,encode(sha256(convert_to(repeat('b',64),'UTF8')),'hex')) on conflict(id) do update set proof_hash=excluded.proof_hash;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;

do $$declare c jsonb;j jsonb;bad jsonb;setup jsonb;doc public.work_documents;sig jsonb;denied boolean;key uuid;customer jsonb;pay jsonb;evidence uuid=gen_random_uuid();begin
 c=public.work_suite('{"action":"capabilities"}');if not (c->>'owner')::boolean or c->>'tax_status'<>'pending' then raise exception 'Owner/pending setup failed';end if;
 key=gen_random_uuid();
 j=public.work_suite(jsonb_build_object('action','journal-save','request_key',key,'data',jsonb_build_object('entry_date',current_date,'currency','NGN','description','Synthetic opening capital','cash_flow','financing','lines','[{"account":"1000","debit_minor":10000,"credit_minor":0},{"account":"3000","debit_minor":0,"credit_minor":9000}]'::jsonb)));
 denied=false;begin perform public.work_suite(jsonb_build_object('action','journal-post','data',jsonb_build_object('id',j->>'id','version',j->>'version')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Disabled accounting posted';end if;
 select payload into setup from public.work_owner_setup where id=1;
 setup=jsonb_set(setup,'{accounting}',jsonb_build_object('enabled',true,'cutover',current_date,'opening_reviewed',true));
 perform public.work_suite(jsonb_build_object('action','setup','version',1,'data',setup));
 if (select payload#>>'{tax,status}' from public.work_owner_setup where id=1)<>'pending' then raise exception 'Saving settings invented a tax status';end if;
 denied=false;begin perform public.work_suite(jsonb_build_object('action','journal-post','data',jsonb_build_object('id',j->>'id','version',j->>'version')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Unbalanced journal posted';end if;
 j=public.work_suite(jsonb_build_object('action','journal-update','data',jsonb_build_object('id',j->>'id','version',j->>'version','entry_date',current_date,'currency','NGN','description','Synthetic balanced capital','cash_flow','financing','lines','[{"account":"1000","debit_minor":10000,"credit_minor":0},{"account":"3000","debit_minor":0,"credit_minor":10000}]'::jsonb)));
 j=public.work_suite(jsonb_build_object('action','journal-post','data',jsonb_build_object('id',j->>'id','version',j->>'version')));
 if j->>'status'<>'posted' then raise exception 'Balanced journal failed';end if;
 select payload into setup from public.work_owner_setup where id=1;
 if public.work_suite('{"action":"capabilities"}') ->> 'financial_year_end' <> '12-31' then raise exception 'Fiscal calendar missing from capabilities';end if;
 denied=false;begin perform public.work_suite(jsonb_build_object('action','setup','version',(select version from public.work_owner_setup where id=1),'data',jsonb_set(setup,'{accounting,year_end}','"06-30"')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Posted accounting year-end was rewritten';end if;

 denied=false;begin perform public.work_suite(jsonb_build_object('action','journal-update','data',jsonb_build_object('id',j->>'id','version',j->>'version','entry_date',current_date,'currency','NGN','description','Attempted rewrite','cash_flow','none','lines',j->'lines')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Posted journal edited';end if;
 c=public.work_suite(jsonb_build_object('action','reports','data',jsonb_build_object('from',current_date,'to',current_date)));if jsonb_array_length(c->'balances')<>2 then raise exception 'Trial balance did not include both accounts';end if;
 perform public.work_suite(jsonb_build_object('action','close','data',jsonb_build_object('through',current_date,'reason','Synthetic reconciled close','reconciled',true)));
 denied=false;begin perform public.work_suite(jsonb_build_object('action','journal-reverse','request_key',gen_random_uuid(),'data',jsonb_build_object('id',j->>'id','version',j->>'version','entry_date',current_date,'reason','Synthetic correcting reversal')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Closed date accepted reversal';end if;
 perform public.work_suite(jsonb_build_object('action','reopen','data',jsonb_build_object('through',current_date,'reason','Synthetic owner reopening','reconciled',true)));
 perform public.work_suite(jsonb_build_object('action','journal-reverse','request_key',gen_random_uuid(),'data',jsonb_build_object('id',j->>'id','version',j->>'version','entry_date',current_date,'reason','Synthetic correcting reversal')));
 perform public.work_suite(jsonb_build_object('action','signature-profile','data',jsonb_build_object('full_name','Fixture Owner','capacity','Owner','image_data','data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aVxkAAAAASUVORK5CYII=')));
 insert into public.work_documents(kind,payload) values('quotation','{"kind":"quotation","customer":{"name":"SIGNATURE FIXTURE","address":"Abuja","email":"fixture@example.invalid","phone":""},"date":"2026-11-01","valid_until":"","currency":"NGN","items":[{"description":"Synthetic item","quantity":1,"unit_minor":10000}],"discount_minor":0,"tax_bps":0,"notes":"Synthetic only","payment_method":"","payment_reference":"","payment_confirmed":false,"source_id":""}') returning * into doc;
 update public.work_documents set status='issued' where id=doc.id returning * into doc;
 denied=false;begin perform public.work_suite(jsonb_build_object('action','sign','data',jsonb_build_object('source_table','work_documents','source_id',doc.id,'source_version',doc.version,'expected_hash',(public.work_suite(jsonb_build_object('action','document-preview','data',jsonb_build_object('source_table','work_documents','source_id',doc.id)))->>'_approval_hash'),'reason','Synthetic owner approval')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Signature allowed without fresh MFA';end if;
 perform set_config('request.jwt.claims',(auth.jwt()||jsonb_build_object('amr',jsonb_build_array(jsonb_build_object('method','totp','timestamp',extract(epoch from now())))))::text,true);
 denied=false;begin perform public.work_suite(jsonb_build_object('action','sign','data',jsonb_build_object('source_table','work_documents','source_id',doc.id,'source_version',doc.version,'expected_hash',repeat('0',64),'reason','Tampered review fingerprint')));exception when raise_exception then denied=true;end;if not denied then raise exception 'Signing accepted a different reviewed fingerprint';end if;
 perform public.work_suite(jsonb_build_object('action','sign','data',jsonb_build_object('source_table','work_documents','source_id',doc.id,'source_version',doc.version,'expected_hash',(public.work_suite(jsonb_build_object('action','document-preview','data',jsonb_build_object('source_table','work_documents','source_id',doc.id)))->>'_approval_hash'),'reason','Synthetic owner approval')));
 sig=public.work_suite(jsonb_build_object('action','signature-read','data',jsonb_build_object('source_table','work_documents','source_id',doc.id)));
 if jsonb_array_length(sig)<>1 or sig#>>'{0,full_name}'<>'Fixture Owner' or not (sig#>>'{0,self_approved}')::boolean then raise exception 'Version-bound owner signature failed';end if;
 perform public.work_suite(jsonb_build_object('action','signature-profile','data',jsonb_build_object('full_name','Updated Owner','capacity','Owner','image_data','data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aVxkAAAAASUVORK5CYII=')));
 if (select full_name from public.work_document_signatures where source_id=doc.id)<>'Fixture Owner' then raise exception 'Profile update rewrote old signature';end if;
 update public.work_documents set status='void',payload=payload||'{"void_reason":"Synthetic correction"}' where id=doc.id;
 sig=public.work_suite(jsonb_build_object('action','signature-read','data',jsonb_build_object('source_table','work_documents','source_id',doc.id)));
 if jsonb_array_length(sig)<>0 then raise exception 'Old signature attached to changed document';end if;
 customer=public.work_business(jsonb_build_object('command','save','entity','customers','version',0,'data',jsonb_build_object('name','SUITE COLLECTION FIXTURE','assigned_to',auth.uid())));
 perform public.work_business(jsonb_build_object('command','misc','action','file','id',evidence,'area','finance','name','Synthetic payment evidence','path',auth.uid()::text||'/'||evidence||'.jpg','size',10,'sha256',repeat('a',64)));
 insert into storage.objects(bucket_id,name) values('work-evidence',auth.uid()::text||'/'||evidence||'.jpg');
 pay=public.work_business(jsonb_build_object('command','payment','request_key',gen_random_uuid(),'data',jsonb_build_object('customer_id',customer->>'id','amount_minor',120050,'currency','NGN','paid_on',current_date,'method','Synthetic transfer','description','Synthetic collected payment','evidence_id',evidence,'confirmed',true)));
 denied=false;begin perform public.work_suite(jsonb_build_object('action','close','data',jsonb_build_object('through',current_date,'reason','Attempted close before source posting','reconciled',true)));exception when raise_exception then denied=true;end;if not denied then raise exception 'Period closed with an unposted business payment';end if;
 j=public.work_suite(jsonb_build_object('action','source','request_key',gen_random_uuid(),'data',jsonb_build_object('source_table','work_payments','source_id',pay->>'id')));
 c=public.work_suite(jsonb_build_object('action','source','request_key',gen_random_uuid(),'data',jsonb_build_object('source_table','work_payments','source_id',pay->>'id')));
 if c->>'id'<>j->>'id' then raise exception 'A payment generated duplicate source journals';end if;
 j=public.work_suite(jsonb_build_object('action','journal-post','data',jsonb_build_object('id',j->>'id','version',j->>'version')));
 if j#>>'{lines,1,account}'<>'2300' or (j#>>'{lines,0,debit_minor}')::bigint<>120050 then raise exception 'Customer payment was misclassified as new sales';end if;
 c=public.work_suite(jsonb_build_object('action','reports','data',jsonb_build_object('from',current_date,'to',current_date)));if (c->>'pending_count')::integer<>0 or (c->>'changed_count')::integer<>0 then raise exception 'Posted source did not reconcile';end if;
 perform public.work_suite(jsonb_build_object('action','journal-reverse','request_key',gen_random_uuid(),'data',jsonb_build_object('id',j->>'id','version',j->>'version','entry_date',current_date,'reason','Synthetic classification correction')));
 c=public.work_suite(jsonb_build_object('action','source','request_key',gen_random_uuid(),'data',jsonb_build_object('source_table','work_payments','source_id',pay->>'id')));
 if c->>'id'=j->>'id' then raise exception 'Reversed source could not create a replacement draft';end if;
 c=public.work_backup_snapshot();if not c ? 'work_ledger_journals' or jsonb_array_length(c->'work_document_signatures')<>1 then raise exception 'New records omitted from manual backup';end if;
 perform public.work_set_member('editor-fixture@example.invalid','staff',true);
 perform public.work_suite('{"action":"responsibilities","data":{"email":"editor-fixture@example.invalid","title":"Projects manager","duties":"Assigned delivery and installation work","ledger_post":false,"period_close":false,"sign_documents":false}}');
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare c jsonb;denied boolean;begin
 c=public.work_suite('{"action":"capabilities"}');if (c->>'owner')::boolean or (c->>'post')::boolean or (c->>'read')::boolean then raise exception 'Staff inherited financial authority';end if;
 if (select count(*) from public.work_owner_setup)<>0 or (select count(*) from public.work_ledger_journals)<>0 then raise exception 'Staff private data leak';end if;
 denied=false;begin perform public.work_suite('{"action":"responsibilities","data":{"email":"editor-fixture@example.invalid","ledger_post":true}}');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Staff self-escalation allowed';end if;
end;$$;
reset role;
set local role anon;
do $$declare denied boolean=false;begin begin perform public.work_suite('{"action":"capabilities"}');exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Anonymous suite access allowed';end if;end;$$;
reset role;
rollback;
select 'PASS: owner tax deferral, protected staff authority, balanced immutable journals, posting activation, period locks/reversals, fresh-MFA version-bound signatures, historical signer retention and backup coverage.' as result;
